from itertools import permutations

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    # d1, d2: dict rider -> bike
    for r in riders:
        if d1[r] == d2[r]:
            return False
    for d in (d1, d2):
        if d["R"] == "F":
            return False
        if d["Y"] == "J":
            return False
    if not (d1["T"] == "H" or d2["T"] == "H"):
        return False
    if d2["S"] != d1["Y"]:
        return False
    return True

sols = []
for p1 in permutations(bikes):
    d1 = dict(zip(riders, p1))
    if d1["T"] != "J":
        continue
    for p2 in permutations(bikes):
        d2 = dict(zip(riders, p2))
        if valid(d1, d2):
            sols.append((d1, d2))

print("Number of valid scenarios with Theresa on J day 1:", len(sols))

options = {
